import sys

def main():
    tok = sys.stdin.read().split()
    q = int(tok[0])
    pos = 1
    key = []
    L = []
    R = []
    root = -1
    out = []
    for _ in range(q):
        op = tok[pos]
        pos += 1
        if op == 'inorder':
            res = []
            stack = []
            cur = root
            while stack or cur != -1:
                while cur != -1:
                    stack.append(cur)
                    cur = L[cur]
                cur = stack.pop()
                res.append(key[cur])
                cur = R[cur]
            out.append(' '.join(map(str, res)) if res else 'EMPTY')
            continue
        x = int(tok[pos])
        pos += 1
        if op == 'insert':
            parent = -1
            cur = root
            while cur != -1 and key[cur] != x:
                parent = cur
                cur = L[cur] if x < key[cur] else R[cur]
            if cur == -1:
                key.append(x)
                L.append(-1)
                R.append(-1)
                node = len(key) - 1
                if parent == -1:
                    root = node
                elif x < key[parent]:
                    L[parent] = node
                else:
                    R[parent] = node
        elif op == 'find':
            cur = root
            while cur != -1 and key[cur] != x:
                cur = L[cur] if x < key[cur] else R[cur]
            out.append('1' if cur != -1 else '0')
        elif op == 'depth':
            cur = root
            d = 0
            while cur != -1 and key[cur] != x:
                cur = L[cur] if x < key[cur] else R[cur]
                d += 1
            out.append(str(d) if cur != -1 else '-1')
        elif op == 'succ':
            cur = root
            best = -1
            while cur != -1:
                if key[cur] > x:
                    best = key[cur]
                    cur = L[cur]
                else:
                    cur = R[cur]
            out.append(str(best))
        else:  # delete
            parent = -1
            cur = root
            while cur != -1 and key[cur] != x:
                parent = cur
                cur = L[cur] if x < key[cur] else R[cur]
            if cur == -1:
                continue
            if L[cur] != -1 and R[cur] != -1:
                sp = cur
                s = R[cur]
                while L[s] != -1:
                    sp = s
                    s = L[s]
                key[cur] = key[s]
                if sp == cur:
                    R[sp] = R[s]
                else:
                    L[sp] = R[s]
            else:
                child = L[cur] if L[cur] != -1 else R[cur]
                if parent == -1:
                    root = child
                elif L[parent] == cur:
                    L[parent] = child
                else:
                    R[parent] = child
    print('\n'.join(out))

main()

