    if t is None:
        return Node(x)
    if x < t.k:
        t.l = insert(t.l, x)
    elif x > t.k:
        t.r = insert(t.r, x)
    return t

def minnode(t):
    while t.l is not None:
        t = t.l
    return t

def delete(t, x):
    if t is None:
        return None
    if x < t.k:
        t.l = delete(t.l, x)
    elif x > t.k:
        t.r = delete(t.r, x)
    else:
        if t.l is None:
            return t.r
        if t.r is None:
            return t.l
        m = minnode(t.r)
        t.k = m.k
        t.r = delete(t.r, m.k)
    return t

